import{_ as a,o as n,c as s,a5 as i}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"Mini Codex v2 Foundation Course: Build a Reviewable, Verifiable Coding Agent from Scratch","description":"An English entry point for the Mini Codex v2 foundation course: build a small coding agent runtime with task state, permission gates, planning, diff review, verification, trace, and eval.","frontmatter":{"title":"Mini Codex v2 Foundation Course: Build a Reviewable, Verifiable Coding Agent from Scratch","description":"An English entry point for the Mini Codex v2 foundation course: build a small coding agent runtime with task state, permission gates, planning, diff review, verification, trace, and eval.","date":"2026-06-19T00:00:00.000Z","lang":"en-US","alternateZh":"/posts/ai-agent-coding-career/mini-codex-v2-open-source","alternateEn":"/posts/ai-agent-coding-career/mini-codex-v2-open-source-en","tags":["Mini Codex","Coding Agent","AI Engineer","Codex","Open Course"],"keywords":["Mini Codex","Coding Agent","Codex tutorial","AI application engineer","open course"]},"headers":[],"relativePath":"posts/ai-agent-coding-career/mini-codex-v2-open-source-en.md","filePath":"posts/ai-agent-coding-career/mini-codex-v2-open-source-en.md","lastUpdated":1790163617000}'),t={name:"posts/ai-agent-coding-career/mini-codex-v2-open-source-en.md"};function o(r,e,p,l,d,c){return n(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="mini-codex-v2-foundation-course" tabindex="-1">Mini Codex v2 Foundation Course <a class="header-anchor" href="#mini-codex-v2-foundation-course" aria-label="Permalink to &quot;Mini Codex v2 Foundation Course&quot;">​</a></h1><p><a href="/blog/posts/ai-agent-coding-career/mini-codex-v2-open-source">中文版</a></p><p>This is not another prompt-template collection, and it is not a thin chatbot wrapper.</p><p>The goal is concrete:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>start from an empty folder</span></span>
<span class="line"><span>-&gt; build a local Mini Codex</span></span>
<span class="line"><span>-&gt; turn one coding request into a trackable, reviewable, verifiable, replayable engineering task</span></span></code></pre></div><p>Primary reading page:</p><p><a href="https://mianshiti.net/welcome/mini-codex" target="_blank" rel="noreferrer">Mini Codex course page</a></p><p>Open-source repository:</p><p><a href="https://github.com/herongdev/min-codex-hands-on-v2" target="_blank" rel="noreferrer">https://github.com/herongdev/min-codex-hands-on-v2</a></p><h2 id="who-this-is-for" tabindex="-1">Who This Is For <a class="header-anchor" href="#who-this-is-for" aria-label="Permalink to &quot;Who This Is For&quot;">​</a></h2><p>This course is for developers who already know basic frontend, backend, or full-stack development and are using tools such as Codex, Cursor, or Claude Code.</p><p>You do not need to master a complex agent framework first. The more important questions are:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Why is a Coding Agent different from a chatbot?</span></span>
<span class="line"><span>Why should the model not touch the file system directly?</span></span>
<span class="line"><span>Why is a prompt not a security boundary?</span></span>
<span class="line"><span>Why should code changes go through a plan and a diff review?</span></span>
<span class="line"><span>Why does &quot;done&quot; require verification evidence?</span></span>
<span class="line"><span>Why do trace and eval decide whether the agent can improve over time?</span></span></code></pre></div><h2 id="what-you-will-build" tabindex="-1">What You Will Build <a class="header-anchor" href="#what-you-will-build" aria-label="Permalink to &quot;What You Will Build&quot;">​</a></h2><p>By the end of the foundation course, you will have a small but complete Mini Codex:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>enter one coding request</span></span>
<span class="line"><span>-&gt; save it as a task</span></span>
<span class="line"><span>-&gt; generate a plan</span></span>
<span class="line"><span>-&gt; wait for your approval</span></span>
<span class="line"><span>-&gt; modify files</span></span>
<span class="line"><span>-&gt; run checks</span></span>
<span class="line"><span>-&gt; save the process</span></span>
<span class="line"><span>-&gt; inspect the result in a desktop workbench</span></span></code></pre></div><p>It does not try to copy every capability of the official Codex product. The foundation course focuses on one thing: making the smallest safe coding-agent loop work.</p><h2 id="course-outline" tabindex="-1">Course Outline <a class="header-anchor" href="#course-outline" aria-label="Permalink to &quot;Course Outline&quot;">​</a></h2><p>The open foundation course includes:</p><ol><li>Lab 00: Environment and practice workspace</li><li>Lab 01: Save the first task</li><li>Lab 02: Pause a task for human approval</li><li>Lab 03: Tool Registry and permission boundaries</li><li>Lab 04: Make the first real code change</li><li>Lab 05: Trace, Replay, and Eval</li><li>Lab 06: Backend API and SSE</li><li>Lab 07: Desktop workbench</li><li>Lab 07b: UI polish and design system</li><li>Lab 08: Compare the boundary with real Codex-style tools</li><li>Real Codex capability upgrade map</li><li>Demo cases</li><li>Eval ledger</li></ol><h2 id="publishing-boundary" tabindex="-1">Publishing Boundary <a class="header-anchor" href="#publishing-boundary" aria-label="Permalink to &quot;Publishing Boundary&quot;">​</a></h2><p>This release open-sources the foundation course and the public upgrade direction only.</p><p>The v2 Advanced course is maintained separately and is not part of this open-source release. The site and repository do not expose private advanced-course paths or commercial-course content.</p><h2 id="why-start-with-the-foundation" tabindex="-1">Why Start With the Foundation <a class="header-anchor" href="#why-start-with-the-foundation" aria-label="Permalink to &quot;Why Start With the Foundation&quot;">​</a></h2><p>The hard part of AI coding is not asking a model to generate code. The hard part is putting generated code inside an engineering system:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>state</span></span>
<span class="line"><span>permissions</span></span>
<span class="line"><span>planning</span></span>
<span class="line"><span>review</span></span>
<span class="line"><span>verification</span></span>
<span class="line"><span>replay</span></span>
<span class="line"><span>evaluation</span></span></code></pre></div><p>Once these foundations are working, RAG, memory, MCP, subagents, Git worktrees, and dashboards become much easier to reason about.</p><p>Start here:</p><p><a href="https://mianshiti.net/welcome/mini-codex" target="_blank" rel="noreferrer">Open the Mini Codex course page</a></p>`,29)])])}const g=a(t,[["render",o]]);export{u as __pageData,g as default};
